// After writing to Primary DB, return the Log Sequence Number (LSN) token
// Route reads to replicas only if they have caught up to the client's write LSN
export async function readUserProfile(
  userId: string,
  clientSeenLsn: bigint,
  primaryDb: DbNode,
  replicaDb: DbNode
) {
  const replicaCurrentLsn = await replicaDb.getReplicationLsn();
  if (replicaCurrentLsn >= clientSeenLsn) {
    return replicaDb.query("SELECT * FROM users WHERE id = $1", [userId]);
  }
  // Replica is lagging; route directly to primary to prevent stale read
  return primaryDb.query("SELECT * FROM users WHERE id = $1", [userId]);
}
